// OpenMod Latency Lens · MIT
// Change this threshold, then rerun the replay.
const SLOW_MS = 100;
let slow = [];
let total = 0;

export function register(on) {
  on('tool.call', async ($, e, next) => {
    const start = await $.clock.now();
    try {
      return await next(e);
    } finally {
      const ms = Math.max(0, (await $.clock.now()) - start);
      total += 1;
      if (ms >= SLOW_MS) {
        slow.push({ tool: e.tool, ms });
        slow = slow.slice(-20);
      }
      $.ui.invalidate('ui.render');
    }
  });

  on('ui.render', { component: 'AbovePrompt' }, ($, e, next) => {
    if (e.props.hasSurvey || !total) return next(e);
    const { Box, Text } = $.ui.resolve(e);
    const recent = slow.slice(-3);
    return Box({ paddingX: 1, children: [
      Text({ color: 'cyan',
        children: 'Latency Lens · ' + total + ' calls'
          + ' · threshold ' + SLOW_MS + 'ms' }),
      Text({ color: slow.length ? 'yellow' : 'green',
        children: recent.length
          ? recent.map(r => r.tool + ' ' + r.ms + 'ms').join(' / ')
          : 'No calls above the threshold.' })
    ] });
  });
}

